const commonKeys=Object.keys(UI.English);
function tr(s){return (UI[state.language]&&UI[state.language][s])||UI.English[s]||s}
function localizeRenderedUI(){
  const root=document.getElementById('app'); if(!root)return;
  const map=UI[state.language]||UI.English;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[]; while(walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(n=>{let v=n.nodeValue; if(!v||!v.trim())return; let t=v.trim(); if(map[t]) n.nodeValue=v.replace(t,map[t]);});
  root.querySelectorAll('input[placeholder], textarea[placeholder]').forEach(el=>{if(el.dataset.basePlaceholder&&!el.dataset.placeholderTranslated){} const key=el.placeholder; if(map[key]){el.dataset.basePlaceholder=key;el.placeholder=map[key];}});
}

function setLanguage(v){state.language=v;localStorage.setItem("ipsakti_language",v);closeMenus();render();}
function setJurisdiction(v){state.jurisdiction=v;localStorage.setItem("ipsakti_jurisdiction",v);closeMenus();render();toast(`${v} selected`)}

function openProfile(){
  closeMenus();
  const existing=document.getElementById('profileModal');
  if(existing) existing.remove();
  const wrap=document.createElement('div');
  wrap.id='profileModal';
  wrap.className='modal-overlay';
  wrap.innerHTML=`<div class="modal profile-modal" role="dialog" aria-modal="true">
    <div class="modal-head"><div><h2>Profile & Account</h2><p>Manage your local prototype profile.</p></div><button class="modal-close" onclick="document.getElementById('profileModal')?.remove()">×</button></div>
    <div class="profile-card"><div class="avatar large">AV</div><div><h3>Ananya Verma</h3><p>Inventor</p><span class="pill green">Active</span></div></div>
    <div class="profile-grid"><div><label>Name</label><strong>Ananya Verma</strong></div><div><label>Role</label><strong>Inventor</strong></div><div><label>Jurisdiction</label><strong>${esc(state.jurisdiction)}</strong></div><div><label>Language</label><strong>${esc(state.language)}</strong></div></div>
    <div class="modal-actions"><button class="btn" onclick="document.getElementById('profileModal')?.remove();openSetting('Workspace Settings')">Open Settings</button><button class="btn primary" onclick="document.getElementById('profileModal')?.remove()">Done</button></div>
  </div>`;
  document.body.appendChild(wrap);
}

function openNotifications(){
  closeMenus();
  document.getElementById('notificationsModal')?.remove();
  const wrap=document.createElement('div'); wrap.id='notificationsModal'; wrap.className='modal-overlay';
  wrap.innerHTML=`<div class="modal notification-modal" role="dialog" aria-modal="true">
    <div class="modal-head"><div><h2>Notifications</h2><p>3 updates need your attention.</p></div><button class="modal-close" onclick="document.getElementById('notificationsModal')?.remove()">×</button></div>
    <div class="notification-list">
      <div class="notification-item"><span class="notification-dot high"></span><div><strong>New update in Drugs & Cosmetics Rules, 1945</strong><small>Regulatory notification · 20 May 2025</small></div></div>
      <div class="notification-item"><span class="notification-dot medium"></span><div><strong>FSSAI draft guidelines on Ayurveda-Aahar</strong><small>Regulatory update · 18 May 2025</small></div></div>
      <div class="notification-item"><span class="notification-dot low"></span><div><strong>Prior-art review recommended</strong><small>IP assessment · Today</small></div></div>
    </div>
    <div class="modal-actions"><button class="btn" onclick="go('reg');document.getElementById('notificationsModal')?.remove()">Review Regulatory Updates</button><button class="btn primary" onclick="document.getElementById('notificationsModal')?.remove()">Done</button></div>
  </div>`;
  document.body.appendChild(wrap);
}
function openHelp(){
  closeMenus();
  document.getElementById('helpModal')?.remove();
  const wrap=document.createElement('div'); wrap.id='helpModal'; wrap.className='modal-overlay';
  wrap.innerHTML=`<div class="modal help-modal" role="dialog" aria-modal="true">
    <div class="modal-head"><div><h2>Need Help?</h2><p>Get guidance on using IP-SAKTI SAHAYAK.</p></div><button class="modal-close" onclick="document.getElementById('helpModal')?.remove()">×</button></div>
    <div class="help-options">
      <button class="quick" onclick="go('ai');document.getElementById('helpModal')?.remove()">🤖 <div><strong>Ask AI Assistant</strong><span>Ask about patentability, prior art, TK, ABS or regulations.</span></div></button>
      <button class="quick" onclick="go('innovation');document.getElementById('helpModal')?.remove()">🧪 <div><strong>Analyze an Innovation</strong><span>Start a new innovation assessment.</span></div></button>
      <button class="quick" onclick="go('reports');document.getElementById('helpModal')?.remove()">📄 <div><strong>Reports & Settings</strong><span>Generate reports and manage your workspace.</span></div></button>
    </div>
    <div class="footer-note">This prototype provides information and decision-support, not legal advice.</div>
  </div>`;
  document.body.appendChild(wrap);
}

function openSetting(name){
  closeMenus();
  document.getElementById('settingsModal')?.remove();
  const wrap=document.createElement('div'); wrap.id='settingsModal'; wrap.className='modal-overlay';
  const saved=(k,d)=>localStorage.getItem('ipsakti_'+k) ?? d;
  let content='';
  if(name==='Profile & Account') content=`<div class="profile-card"><div class="avatar large">AV</div><div><h3>Ananya Verma</h3><p>Inventor</p><span class="pill green">Active</span></div></div><div class="profile-grid"><div><label>Name</label><strong>Ananya Verma</strong></div><div><label>Role</label><strong>Inventor</strong></div><div><label>Country / Jurisdiction</label><strong>${esc(state.jurisdiction)}</strong></div><div><label>Language</label><strong>${esc(state.language)}</strong></div></div>`;
  else if(name==='Workspace Settings') content=`<div class="settings-form"><label>Default jurisdiction</label><select id="setCountry"><option>India</option><option>United States</option><option>European Union</option><option>Australia</option><option>UAE</option></select><label>Default language</label><select id="setLanguage">${LANGUAGES.map(x=>`<option>${x}</option>`).join('')}</select><label>Dashboard view</label><select id="setView"><option>Detailed</option><option>Compact</option></select></div>`;
  else if(name==='Notification Preferences') content=`<div class="settings-checks"><label><input type="checkbox" id="nReg" ${saved('notify_reg','true')==='true'?'checked':''}> Regulatory alerts</label><label><input type="checkbox" id="nPrior" ${saved('notify_prior','true')==='true'?'checked':''}> Prior-art review alerts</label><label><input type="checkbox" id="nRisk" ${saved('notify_risk','true')==='true'?'checked':''}> Risk and action reminders</label><label><input type="checkbox" id="nReport" ${saved('notify_report','true')==='true'?'checked':''}> Report notifications</label></div>`;
  else if(name==='Data & Privacy') content=`<div class="settings-checks"><label><input type="checkbox" id="audit" ${saved('audit','true')==='true'?'checked':''}> Enable audit logging</label><label><input type="checkbox" id="localOnly" ${saved('local_only','true')==='true'?'checked':''}> Keep prototype data local</label></div><div class="footer-note">This prototype stores workspace data locally. Do not enter confidential or sensitive legal information.</div>`;
  else if(name==='Report Preferences') content=`<div class="settings-form"><label>Default report format</label><select id="reportFormat"><option>Detailed PDF-ready report</option><option>Executive summary</option><option>Evidence-focused report</option></select><label>Include citations</label><select id="citations"><option>Yes</option><option>No</option></select></div>`;
  else content=`<div class="settings-form"><label>Theme</label><select id="theme"><option>System default</option><option>Light</option></select><label>Interface density</label><select id="density"><option>Comfortable</option><option>Compact</option></select><label>AI response style</label><select id="aiStyle"><option>Clear and concise</option><option>Detailed</option></select></div>`;
  wrap.innerHTML=`<div class="modal settings-modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${esc(name)}</h2><p>Manage ${esc(name.toLowerCase())} for this prototype.</p></div><button class="modal-close" onclick="document.getElementById('settingsModal')?.remove()">×</button></div>${content}<div class="modal-actions"><button class="btn" onclick="document.getElementById('settingsModal')?.remove()">Cancel</button><button class="btn primary" onclick="saveSetting('${name.replace(/'/g,"\\'")}')">Save changes</button></div></div>`;
  document.body.appendChild(wrap);
  if(name==='Workspace Settings'){document.getElementById('setCountry').value=state.jurisdiction;document.getElementById('setLanguage').value=state.language;document.getElementById('setView').value=saved('view','Detailed')}
}
function saveSetting(name){
  if(name==='Workspace Settings'){setJurisdiction(document.getElementById('setCountry').value);setLanguage(document.getElementById('setLanguage').value);localStorage.setItem('ipsakti_view',document.getElementById('setView').value);document.getElementById('settingsModal')?.remove();return;}
  if(name==='Notification Preferences'){[['notify_reg','nReg'],['notify_prior','nPrior'],['notify_risk','nRisk'],['notify_report','nReport']].forEach(([k,id])=>localStorage.setItem('ipsakti_'+k,document.getElementById(id).checked));}
  if(name==='Data & Privacy'){localStorage.setItem('ipsakti_audit',document.getElementById('audit').checked);localStorage.setItem('ipsakti_local_only',document.getElementById('localOnly').checked);}
  document.getElementById('settingsModal')?.remove(); toast(name+' saved');
}
function toggleMenu(id){const el=document.getElementById(id);if(!el)return;document.querySelectorAll('.topmenu').forEach(x=>{if(x!==el)x.style.display='none'});el.style.display=el.style.display==='block'?'none':'block'}
function closeMenus(){document.querySelectorAll('.topmenu').forEach(x=>x.style.display='none')}


