function ai(){
 const i=current()||{};
 return pagehead("AI Assistant","Your intelligent partner for IP, TK, regulatory and innovation support",`<button class="btn">▣ Assistant Guide</button>`)+
 `<div class="grid g2"><div><div class="card"><h3>Quick Actions</h3>${[["⌕","Check Patentability","Assess novelty & patentability"],["⌕","Find Prior Art","Search patents & literature"],["🌿","ABS Compliance Check","Check access & benefit sharing"],["⚖","Regulatory Pathway","Find applicable regulations"],["▣","Draft Documents","Generate reports & letters"],["▤","Explain a Concept","Get simple explanations"]].map((x,n)=>`<button class="quick ${n%3===1?"blue":n%3===2?"purple":""}" style="width:100%;margin:4px 0;text-align:left" onclick="ask('${x[1]}')">${x[0]} <div><strong>${x[1]}</strong><span>${x[2]}</span></div></button>`).join("")}</div><div class="card" style="margin-top:18px"><h3>Suggested Prompts</h3>${["Is my innovation patentable?","Find similar patents for my idea","What TK records exist for this use?","What regulations apply to herbal oils?","How to comply with ABS in India?"].map(x=>`<div class="riskline" onclick="ask('${x}')">${x}<span>›</span></div>`).join("")}</div></div>
 <div class="card chat"><div class="messages" id="messages"><div class="bubble bot">🤖 <b>Hello Ananya! 👋</b><br><br>I’m your IP-SAKTI AI Assistant. I can help you with patentability, prior art search, TK & biodiversity, regulations, and more. How can I assist you today?</div><div class="bubble user">Is my innovation “${esc(i.name||"HerboRelief Pain Relief Oil")}” likely to be patentable?</div><div class="bubble bot">🟢 <b>Based on the information available in IP-SAKTI:</b><br><br>🟢 TK Similarity Score: Moderate (62%)<br>🟢 Novelty Assessment: Possible – some similar uses found but formulation appears novel.<br>🟢 Prior Art: 3 potentially relevant patents identified.<br>🟢 Patentability Likelihood: <span class="pill orange">Moderate</span><br><br>I recommend conducting a detailed prior art search and reviewing claims with a patent expert.</div></div><div class="composer"><input id="chatInput" placeholder="Ask me anything about IP, TK, regulations, or your innovation..." onkeydown="if(event.key==='Enter')sendChat()"><button class="send" onclick="sendChat()">➤</button></div><small class="muted" style="margin-top:8px">ⓘ AI responses are for informational purposes only and not legal advice.</small></div></div>`;
}
function ask(q){go("ai");setTimeout(()=>{document.getElementById("chatInput").value=q;sendChat()},100)}
async function sendChat(){const input=document.getElementById("chatInput"),q=input.value.trim();if(!q)return;const m=document.getElementById("messages");m.innerHTML+=`<div class="bubble user">${esc(q)}</div>`;input.value="";const r=await api("/ai/chat",{method:"POST",body:JSON.stringify({message:q,language:state.language,jurisdiction:state.jurisdiction})});let cites=(r.citations||[]).map((c,i)=>`<div style="margin-top:8px;padding:8px;border-left:3px solid #08783f;background:#f6fbf8"><b>Source ${i+1}: ${esc(c.title)}</b><div class="sub">${esc(c.source)}</div><small>${esc(c.snippet)}</small></div>`).join("");
 m.innerHTML+=`<div class="bubble bot">🤖 ${esc(r.answer)}<br><br><b>Confidence: ${esc(r.confidence)}%</b>${cites}<br><small class="muted">${r.time} · Information, not legal advice</small></div>`;m.scrollTop=m.scrollHeight}

