 <div class="card" style="margin-top:18px"><h3>Settings</h3><div class="grid g3">${["Profile & Account","Workspace Settings","Notification Preferences","Data & Privacy","Report Preferences","System Preferences"].map(x=>`<button class="quick" onclick="openSetting('${x}')">⚙ <div><strong>${x}</strong><span>Manage preferences and settings　›</span></div></button>`).join("")}</div></div>
