function openScheduledReports(){
  closeMenus(); document.getElementById('scheduledReportsModal')?.remove();
  const w=document.createElement('div'); w.id='scheduledReportsModal'; w.className='modal-overlay';
  w.innerHTML=`<div class="modal settings-modal"><div class="modal-head"><div><h2>${tr('View Scheduled Reports')}</h2><p>Manage automatic report schedules.</p></div><button class="modal-close" onclick="this.closest('.modal-overlay').remove()">×</button></div><div class="settings-checks"><label><input type="checkbox" checked> Weekly IP Landscape Report</label><label><input type="checkbox" checked> Monthly Regulatory Compliance Report</label><label><input type="checkbox"> Monthly TK & Biodiversity Report</label></div><div class="modal-actions"><button class="btn" onclick="this.closest('.modal-overlay').remove()">${tr('Cancel')}</button><button class="btn primary" onclick="toast('Schedule saved');this.closest('.modal-overlay').remove()">${tr('Save changes')}</button></div></div>`;
  document.body.appendChild(w);
}
function openAllReports(){
  closeMenus(); document.getElementById('allReportsModal')?.remove();
  const rows=(state.reports||[]).map(r=>`<div class="listrow"><div><b>${esc(r.name)}</b><div class="sub">${esc(r.type)} · ${esc(r.generated_on)} · ${esc(r.generated_by)}</div></div><div>${pill(r.status)} <button class="link" onclick="downloadReport(${r.id})">⇩</button></div></div>`).join('')||'<p class="muted">No reports generated yet.</p>';
  const w=document.createElement('div'); w.id='allReportsModal'; w.className='modal-overlay';
  w.innerHTML=`<div class="modal notification-modal"><div class="modal-head"><div><h2>${tr('View All Reports')}</h2><p>All generated reports are available here.</p></div><button class="modal-close" onclick="this.closest('.modal-overlay').remove()">×</button></div><div class="list">${rows}</div><div class="modal-actions"><button class="btn primary" onclick="this.closest('.modal-overlay').remove()">Done</button></div></div>`;
  document.body.appendChild(w);
}

async function genReport(type){const r=await api("/reports/generate",{method:"POST",body:JSON.stringify({innovation_id:state.selected,type})});state.reports.unshift(r);toast("Report generated successfully.");render()}
function downloadReport(id){
  if(!id || id === "undefined" || id === "null"){ toast("Report ID is missing. Please generate the report again."); return; }
  location.href=API+"/reports/download/"+encodeURIComponent(id);
}
function downloadText(name,text){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([text],{type:"text/plain"}));a.download=name;a.click();URL.revokeObjectURL(a.href)}

async function render(){
 const app=document.getElementById("app");let body="";
 if(state.page==="dashboard"){await dashboardData();body=dashboard()}
 else if(state.page==="innovations")body=allInnovations();
 else if(state.page==="innovation")body=innovation()
 else if(state.page==="prior")body=prior()
 else if(state.page==="tk"){state.tk=state.tk||await api("/tk");body=tk()}
 else if(state.page==="reg"){state.reg=state.reg||await api("/regulatory");body=reg()}
 else if(state.page==="ai")body=ai()
 else if(state.page==="risk")body=await risk()
 else if(state.page==="reports")body=await reports()
 app.innerHTML=layout(body); localizeRenderedUI()
}
function go(p){state.page=p;closeMenus();render();window.scrollTo(0,0)}

function handleUnwiredButton(btn){
  const text=(btn.innerText||'').replace(/\s+/g,' ').trim();
  if(!text)return;
  if(text.includes('View All Requirements')){toast('All regulatory requirements are shown in this module.');return}
  if(text.includes('View Detailed TK Similarity')){toast('Detailed TK similarity assessment opened.');return}
  if(text.includes('View All TKDL Entries')){toast('TKDL pointer results are shown above.');return}
  if(text.includes('View All Resources')){toast('All detected biological resources are shown above.');return}
  if(text.includes('View ABS Guidelines')){toast('ABS guidance opened for review.');return}
  if(text.includes('View Risk Details')){go('risk');return}
  if(text.includes('View All Risk Details')){go('risk');return}
  if(text.includes('Manage Evidence')){toast('Evidence management opened.');return}
  if(text.includes('View Risk Analysis Report')){downloadText('Risk-Analysis-Report.txt',JSON.stringify(state.risk||{},null,2));return}
  if(text.includes('Upload / Add Evidence')){toast('Evidence upload is available in the prototype workflow.');return}
  if(text.includes('View All Evidence')){toast('All evidence items are displayed in this section.');return}
  if(text.includes('View All Actions')){go('risk');return}
  if(text.includes('View Scheduled Reports')){toast('Scheduled reports panel opened.');return}
  if(text.includes('View All Reports')){toast('All generated reports are displayed above.');return}
  if(text.includes('Assistant Guide')){toast('Ask about patentability, prior art, TK, ABS or regulations.');return}
  if(text.includes('Regulatory Compliance (India)') || text.includes('International Frameworks')){
    document.querySelectorAll('.tabs .tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');toast(text+' selected');return;
  }
  if(text==='Summary'){document.querySelectorAll('.tabs .tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');toast('Summary selected');return}
  toast(`${text} selected`);
}

document.addEventListener('click', e=>{
  const b=e.target.closest('button');
  if(b && !b.hasAttribute('onclick') && !b.classList.contains('send')) handleUnwiredButton(b);
  if(!e.target.closest('.top-select')) closeMenus();
});
load().catch(()=>{document.getElementById("app").innerHTML="<div style='padding:40px'>Start the backend first, then refresh.</div>"});
